import{z as s,x as A,o as r,c as d,q as n,j as l,D as E,d as B,s as o,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"国家风险溢价","description":"","frontmatter":{"title":"国家风险溢价","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/country-risk-premium.md","filePath":"econ/country-risk-premium.md","lastUpdated":1791413859000}'),p={name:"econ/country-risk-premium.md"};function C(m,a,u,D,b,c){const t=A("Mermaid");return r(),d("div",null,[a[2]||(a[2]=n('<h1 id="国家风险溢价" tabindex="-1">国家风险溢价 <a class="header-anchor" href="#国家风险溢价" aria-label="Permalink to &quot;国家风险溢价&quot;">​</a></h1><div class="epigraph"><p>国家风险不是把主权利差一律加进每个项目的折现率；能分散的宏观冲击与不能分散的征收、外汇管制，应当分别进折现率或进现金流情景。</p><footer>—— 据 Damodaran 对国家风险溢价的操作讨论；Erb, Harvey and Viskanta, Journal of Portfolio Management 1996；Brealey, Myers and Allen 整理</footer></div><p><a href="/econ/inflation-valuation">上一课</a>要求货币口径匹配。本课缺口是跨境项目：主权违约、征收、资本管制是否进入 \\(r\\)，以及「国家 beta」与公司/项目暴露的差别。资本预算单元到此收束。不重写 Fisher 方程，不把新兴市场股票异象写成量化栏因子。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CAPM 的市场是谁的市场？全球一体化下，可分散的国别冲击不进全球投资者的要求回报；分割市场下，本国投资者的市场组合含大量本国风险，溢价更高。实务把主权债券利差加在成熟市场溢价上，当作国家风险溢价（CRP），再乘一个公司对国家的暴露。缺口是：主权利差补偿的是本币国债的违约与流动性，不是每个项目的经营风险；出口商收入在美元、成本在本地，暴露不是 1。把 CRP 一律加进 WACC，又把同一征收风险在情景里再扣一次现金，是双重计算。</p><p>Tirole：政治风险往往不可保、不可分散到全球股东之外，应进期望现金流（征收概率 × 损失）或进短于名义期限的回收路径。Brealey–Myers：能买保险或对冲的，进成本不进 \\(r\\)；不能的，才考虑溢价。</p><p><span class="marginnote">数字实例：某国主权利差 4%。出口厂收入与资产七成可转移（\\(\\lambda=0.3\\)），粗线性法只加 \\(4\\%\\times0.3=1.2\\%\\) 到折现率；当地不可移动的水电站 \\(\\lambda=1\\)，才可能加满 4%——同一利差，不同项目暴露完全不同。</span></p><p><span class="marginnote">Erb–Harvey–Viskanta 用国家信用风险度量与股票回报做截面联系。这是投资组合证据，不是许可证把同一利差加到水电与出口加工的同一个 WACC 上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先定投资者与计价货币。全球投资者 + 美元现金：用美元 \\(r_f\\) + 全球溢价 \\(\\times\\) 项目对全球市场的 beta；国家特有的征收与管制用情景减期望现金，或加一个与暴露成比例的 CRP。本地投资者 + 本币现金：用本币名义 \\(r\\)（已含通胀与本币风险溢价），不要再把美元主权利差加一层。</p><p>暴露：\\(\\lambda=\\) 收入/成本/资产在该国不可转移的比例。CRP \\(\\times\\lambda\\) 加在 \\(r_U\\) 上是粗糙线性。更好：现金流按政权情景加权，折现仍用无征收世界的 \\(r_U\\)。两种方法选一种，写进假设。</p>',11)),(r(),l(i,null,{default:E(()=>[o(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20INT%5B%22%E5%B8%82%E5%9C%BA%E6%98%AF%E5%90%A6%E4%B8%80%E4%BD%93%E5%8C%96%22%5D%20--%3E%20R%5B%22%E7%94%A8%E8%B0%81%E7%9A%84%E5%B8%82%E5%9C%BA%E6%BA%A2%E4%BB%B7%22%5D%0A%20%20EXP%5B%22%E9%A1%B9%E7%9B%AE%E6%9A%B4%E9%9C%B2%20%CE%BB%22%5D%20--%3E%20CRP%5B%22%E6%98%AF%E5%90%A6%E5%8A%A0%20CRP%22%5D%0A%20%20CF%5B%22%E5%BE%81%E6%94%B6%20%2F%20%E7%AE%A1%E5%88%B6%E6%83%85%E6%99%AF%22%5D%20--%3E%20CASH%5B%22%E5%87%8F%E6%9C%9F%E6%9C%9B%E7%8E%B0%E9%87%91%22%5D%0A%20%20R%20--%3E%20CHOOSE%5B%22%E5%8A%A0%20r%20%E6%88%96%E5%87%8F%E7%8E%B0%E9%87%91%2C%20%E5%8B%BF%E5%8F%8C%E9%87%8D%22%5D%0A%20%20CASH%20--%3E%20CHOOSE%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"可比：用同国纯业务的 \\(\\beta_A\\) 已含部分国家周期；再加全额主权利差会部分重复。Damodaran 的 \\(\\lambda\\) 调整是为减轻重复，不是精确识别。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制是风险由谁承担、能否交易。全球 CAPM 下，国家消费与全球市场的协方差进 beta；征收是跳跃、常与全球 \\(R_m\\) 弱相关，但对不可分散的控制权损失是财富税。加折现率把后期现金压得更狠（期限越长罚得越重）；征收若是一次没收，现金流情景更贴。长期特许权对折现率法极敏感——又回到终值课：一个 CRP 可以把 NPV 符号改掉。",-1)),(r(),l(i,null,{default:E(()=>[o(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E4%B8%80%E7%B1%BB%E5%9B%BD%E5%AE%B6%E9%A3%8E%E9%99%A9%22%5D%20--%3E%20Q1%7B%22%E8%83%BD%E5%90%A6%E4%BA%A4%E6%98%93%20%2F%20%E5%88%86%E6%95%A3%20%2F%20%E6%8A%95%E4%BF%9D%3F%22%7D%0A%20%20Q1%20--%3E%7C%E8%83%BD%E5%AF%B9%E5%86%B2%E6%88%96%E6%8A%95%E4%BF%9D%7C%20COST%5B%22%E8%BF%9B%E6%88%90%E6%9C%AC%E4%B8%8E%E4%BF%9D%E8%B4%B9%EF%BC%9A%E6%94%B9%E7%8E%B0%E9%87%91%E6%B5%81%22%5D%0A%20%20Q1%20--%3E%7C%E4%B8%8D%E8%83%BD%EF%BC%9A%E5%BE%81%E6%94%B6%20%2F%20%E5%A4%96%E6%B1%87%E7%AE%A1%E5%88%B6%7C%20Q2%7B%22%E5%86%B2%E5%87%BB%E6%98%AF%E4%BB%80%E4%B9%88%E5%BD%A2%E7%8A%B6%3F%22%7D%0A%20%20Q2%20--%3E%7C%E8%B7%B3%E8%B7%83%E5%BC%8F%E3%80%81%E4%B8%8E%E5%B8%82%E5%9C%BA%E5%BC%B1%E7%9B%B8%E5%85%B3%7C%20SCEN%5B%22%E6%8C%89%E6%83%85%E6%99%AF%E5%8A%A0%E6%9D%83%E6%9C%9F%E6%9C%9B%E7%8E%B0%E9%87%91%22%5D%0A%20%20Q2%20--%3E%7C%E7%B3%BB%E7%BB%9F%E6%80%A7%E3%80%81%E6%8C%81%E7%BB%AD%E5%AD%98%E5%9C%A8%7C%20RATE%5B%22%E6%8C%89%E6%9A%B4%E9%9C%B2%20%CE%BB%20%E5%8A%A0%E8%BF%9B%E6%8A%98%E7%8E%B0%E7%8E%87%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">数字实例：同一笔第 10 年到账的 100，折现率多加 3% 就被压到约 \\(100/1.03^{10}\\approx74\\)；第 20 年只剩约 55。征收若发生在第 3 年，用情景减现只损失当年，用溢价则以后每年都打折——这就是「期限越长罚得越重」。</span></p><p>宏观课序在前：主权违约、美元主导、资本管制已有总量语言。本课不重写 Eaton–Gersovitz，只把企业项目接到：政府是合同的一方，NPV 是在该合同可执行前提下的现值。</p><h3 id="不要用国家评级替代项目分析" tabindex="-1">不要用国家评级替代项目分析 <a class="header-anchor" href="#不要用国家评级替代项目分析" aria-label="Permalink to &quot;不要用国家评级替代项目分析&quot;">​</a></h3><p>同一国的资源特许与移动支付，征收与外汇暴露不同。国家评级是主权债，不是项目 beta。母公司担保、离岸结构、双边投资协定，改变的是 \\(\\lambda\\) 与回收，不是把 CRP 设为零的借口——转移定价与担保本身有成本，应进 APV。</p><p><span class="marginnote">常见误区：初学者容易把国家评级（主权债的违约度量）当成项目的风险画像。同一国里，资源特许权与跨境移动支付业务的征收、外汇暴露天差地别；评级只能粗筛，替代不了逐项目的 \\(\\lambda\\) 与情景分析。</span></p><p><span class="marginnote">双重计算的典型：WACC 加主权利差，情景再假设超通胀与冻结股息。选一种主通道，另一种只作敏感性。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课结束「把项目折成今天的钱」。不估计全球市场溢价的「正确」数字，不进入限价簿。下一单元资本结构动态：Leland 把税盾与违约放进扩散，项目 \\(V\\) 变成状态变量——贴现装置带到那里，不再争论 IRR。</p><p>后课默认：国家风险要么进暴露调整的溢价，要么进现金流情景，禁止双重；货币口径承接上一课。项目暴露不是主权利差本身。</p><p>宏观课序在前给出主权与美元；本课只做企业资本预算的接口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>国家风险溢价不是主权利差对每个项目的一律加成。</li><li>一体化、计价货币、暴露 \\(\\lambda\\) 决定加 \\(r\\) 还是减现金；二者只选主通道。</li><li>资本预算单元收束：NPV 口径、WACC/APV、终值、倍数、RI、期权、租赁、NWC、通胀与国家风险已经齐。</li><li>出处：Erb, Harvey and Viskanta 1996；Damodaran；Brealey, Myers and Allen。</li></ul>',12))])}const F=s(p,[["render",C]]);export{P as __pageData,F as default};
